BEGIN;
CREATE FUNCTION pg_temp.contact_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; END $$;
CREATE FUNCTION pg_temp.contact_denied(stmt text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE stmt; EXCEPTION WHEN insufficient_privilege THEN RETURN; END; RAISE EXCEPTION 'Unexpected permission: %',stmt; END $$;
GRANT EXECUTE ON FUNCTION pg_temp.contact_assert(boolean,text),pg_temp.contact_denied(text) TO anon,authenticated,service_role;
INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data)
VALUES ('e0000000-0000-0000-0000-000000000001','old@example.invalid',now(),'{"pawconnect_onboarding_version":"1","phone":"333-bad","full_name":"Synthetic"}'),
 ('e0000000-0000-0000-0000-000000000002','second@example.invalid',NULL,'{"pawconnect_onboarding_version":"1"}');
SELECT pg_temp.contact_assert((SELECT NOT email_verified FROM public.profiles WHERE id='e0000000-0000-0000-0000-000000000001'),'autoconfirm not proof');
UPDATE auth.users SET confirmation_sent_at=now()-interval '1 minute',email_confirmed_at=now() WHERE id='e0000000-0000-0000-0000-000000000002';
SELECT pg_temp.contact_assert((SELECT email_verified FROM public.profiles WHERE id='e0000000-0000-0000-0000-000000000002'),'native confirmation synchronized');
UPDATE public.profiles SET email_verified=true,phone_verified=true WHERE id='e0000000-0000-0000-0000-000000000001';
SELECT pg_temp.contact_assert((SELECT NOT email_verified AND NOT phone_verified FROM public.profiles WHERE id='e0000000-0000-0000-0000-000000000001'),'legacy flag update cannot verify');
SET LOCAL ROLE service_role;
SELECT pg_temp.contact_assert(public.begin_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000011','phone','+393334445555',repeat('a',64),repeat('b',64))->>'error'='other_contact_unverified','unverified alternate cannot authorize');
SELECT public.begin_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000012','email','old@example.invalid',repeat('a',64),repeat('b',64));
SELECT pg_temp.contact_assert(public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000012',repeat('a',64),'')->>'error'='expired','undelivered code denied');
SELECT public.mark_account_contact_delivery('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000012',true);
SELECT pg_temp.contact_assert(public.complete_account_contact('e0000000-0000-0000-0000-000000000002','e0000000-0000-0000-0000-000000000012',repeat('a',64),'')->>'error'='expired','foreign challenge denied');
SELECT pg_temp.contact_assert(public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000012',repeat('b',64),'')->>'error'='invalid_code','bad code');
SELECT pg_temp.contact_assert((public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000012',repeat('a',64),'')->>'applied')::boolean,'email proof');
SELECT pg_temp.contact_assert(public.begin_account_contact('e0000000-0000-0000-0000-000000000001',gen_random_uuid(),'phone','+393334445555',repeat('a',64),repeat('b',64))->>'error'='rate_limited','rate limit');
RESET ROLE;
UPDATE pc_private.contact_challenges SET created_at=now()-interval '2 minutes';
SET LOCAL ROLE service_role;
SELECT pg_temp.contact_assert(public.begin_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000013','phone','+39 333 444 5555',repeat('a',64),repeat('b',64))->>'otherTarget'='old@example.invalid','correct malformed phone with email');
SELECT public.mark_account_contact_delivery('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000013',true);
SELECT pg_temp.contact_assert(public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000013',repeat('a',64),'')->>'error'='invalid_code','both codes required');
SELECT pg_temp.contact_assert((public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000013',repeat('a',64),repeat('b',64))->>'applied')::boolean,'phone change');
SELECT pg_temp.contact_assert((public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000013',repeat('a',64),repeat('b',64))->>'applied')::boolean,'idempotent response');
RESET ROLE;
SELECT pg_temp.contact_assert((SELECT phone='+393334445555' AND phone_verified FROM public.profiles WHERE id='e0000000-0000-0000-0000-000000000001'),'new phone synchronized');
SELECT pg_temp.contact_denied($q$UPDATE auth.users SET email='unproved@example.invalid' WHERE id='e0000000-0000-0000-0000-000000000001'$q$);
UPDATE pc_private.contact_challenges SET created_at=now()-interval '2 minutes';
SET LOCAL ROLE service_role;
SELECT public.begin_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000014','email','new@example.invalid',repeat('a',64),repeat('b',64));
SELECT public.mark_account_contact_delivery('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000014',true);
SELECT pg_temp.contact_assert(public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000014',repeat('a',64),repeat('b',64))->>'applyEmail'='new@example.invalid','email grant issued');
RESET ROLE;
SELECT pg_temp.contact_assert((SELECT email='old@example.invalid' FROM auth.users WHERE id='e0000000-0000-0000-0000-000000000001'),'email preserved until Auth commits');
UPDATE auth.users SET email='new@example.invalid' WHERE id='e0000000-0000-0000-0000-000000000001';
SELECT pg_temp.contact_assert((SELECT email='new@example.invalid' AND email_verified FROM public.profiles WHERE id='e0000000-0000-0000-0000-000000000001'),'login email and profile agree');
SELECT pg_temp.contact_assert((SELECT state='applied' FROM pc_private.contact_challenges WHERE id='e0000000-0000-0000-0000-000000000014'),'Auth consumes grant');
SELECT pg_temp.contact_denied($q$UPDATE auth.users SET email='old@example.invalid' WHERE id='e0000000-0000-0000-0000-000000000001'$q$);
UPDATE pc_private.contact_challenges SET created_at=now()-interval '2 minutes';
SET LOCAL ROLE service_role;
SELECT public.begin_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000015','phone','+393334445556',repeat('a',64),repeat('b',64));
SELECT public.mark_account_contact_delivery('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000015',true);
SELECT public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000015',repeat('c',64),repeat('b',64)) FROM generate_series(1,5);
SELECT pg_temp.contact_assert(public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000015',repeat('a',64),repeat('b',64))->>'error'='too_many_attempts','attempt limit persists');
RESET ROLE;
UPDATE pc_private.contact_challenges SET created_at=now()-interval '2 hours';
SET LOCAL ROLE service_role;
SELECT public.begin_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000016','email','next@example.invalid',repeat('a',64),repeat('b',64));
SELECT public.mark_account_contact_delivery('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000016',true);
SELECT public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000016',repeat('a',64),repeat('b',64));
RESET ROLE;
UPDATE pc_private.contact_proofs SET verified_at=clock_timestamp() WHERE user_id='e0000000-0000-0000-0000-000000000001' AND kind='phone';
SELECT pg_temp.contact_denied($q$UPDATE auth.users SET email='next@example.invalid' WHERE id='e0000000-0000-0000-0000-000000000001'$q$);
UPDATE pc_private.contact_challenges SET expires_at=now()-interval '1 second' WHERE id='e0000000-0000-0000-0000-000000000016';
SET LOCAL ROLE service_role;
SELECT pg_temp.contact_assert(public.complete_account_contact('e0000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000016',repeat('a',64),repeat('b',64))->>'error'='expired','expired grant denied');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e0000000-0000-0000-0000-000000000001',true);
SELECT pg_temp.contact_denied($q$SELECT * FROM pc_private.contact_proofs$q$);
SELECT pg_temp.contact_denied($q$SELECT public.account_contact_status('e0000000-0000-0000-0000-000000000001')$q$);
SELECT pg_temp.contact_denied($q$UPDATE public.profiles SET phone='+393330000000' WHERE id='e0000000-0000-0000-0000-000000000001'$q$);
RESET ROLE;
SET LOCAL ROLE anon;
SELECT pg_temp.contact_denied($q$SELECT * FROM pc_private.contact_challenges$q$);
SELECT pg_temp.contact_denied($q$SELECT public.account_contact_status('e0000000-0000-0000-0000-000000000001')$q$);
RESET ROLE;
SELECT pg_temp.contact_assert(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('account_contact_status','begin_account_contact','complete_account_contact','mark_account_contact_delivery') AND p.prosecdef),'public wrappers are invoker');
ROLLBACK;
